public final class PlanWizard {
 public interface Callback{void saved();}
 private PlanWizard(){}
 private static final int BG=Color.rgb(14,16,20),SURFACE=Color.rgb(24,27,33),SURFACE2=Color.rgb(32,36,43),TEXT=Color.rgb(245,245,245),MUTED=Color.rgb(157,163,172),ORANGE=Color.rgb(255,139,0);
 private static final Locale TR=new Locale("tr","TR");
 private static class Draft{String key,title,icon,date,type=Plan.HOURLY,start="",end="",repeat=Plan.REPEAT_NONE;JSONObject details=new JSONObject();Draft(String d){date=d;}}
 public static void show(Activity a,List<Plan> plans,String date,Callback cb){showCategory(a,plans,new Draft(date),cb);}
 private static Dialog dialog(Activity a){Dialog d=new Dialog(a);d.setCancelable(true);return d;}
 private static void fit(Dialog d,Activity a,float frac){Window w=d.getWindow();if(w!=null){w.setBackgroundDrawableResource(android.R.color.transparent);w.setLayout((int)(a.getResources().getDisplayMetrics().widthPixels*frac),-2);}}
 private static TextView label(Activity a,String s){return txt(a,s,12,MUTED,true);}
 private static int dp(Context c,int v){return (int)(v*c.getResources().getDisplayMetrics().density+.5f);}
 private static void showCategory(Activity a,List<Plan> plans,Draft d,Callback cb){
  Dialog x=dialog(a);LinearLayout box=box(a);header(a,box,"Yeni plan","Önce ne yapacağını seç.",x);GridLayout grid=new GridLayout(a);grid.setColumnCount(2);
  String[][] cats={{"📚","Kitap / Okuma","book"},{"💼","İş","work"},{"🎬","Video Edit","video"},{"🏋️","Spor","sport"},{"🕌","İbadet","faith"},{"📍","Randevu","appointment"},{"🍳","Yemek","food"},{"◉","Kişisel","personal"}};
  for(String[] c:cats){LinearLayout card=category(a,c[0],c[1]);GridLayout.LayoutParams p=new GridLayout.LayoutParams(GridLayout.spec(GridLayout.UNDEFINED,1f),GridLayout.spec(GridLayout.UNDEFINED,1f));p.width=0;p.height=dp(a,86);p.setMargins(dp(a,4),dp(a,4),dp(a,4),dp(a,4));grid.addView(card,p);card.setOnClickListener(v->{d.key=c[2];d.icon=c[0];x.dismiss();details(a,plans,d,cb);});}
  box.addView(grid,mt(a,10));x.setContentView(box);x.show();fit(x,a,.95f);
 }
 private static void details(Activity a,List<Plan> plans,Draft d,Callback cb){
  Dialog x=dialog(a);ScrollView scroll=new ScrollView(a);LinearLayout box=box(a);header(a,box,d.icon+"  "+label(d.key),"1 / 2  ·  Bu kategoriye özel bilgiler.",x);List<EditText> fs=new java.util.ArrayList<>();String[] ls=fields(d.key);
  for(int i=0;i<ls.length;i++){EditText e=input(a,ls[i]);if("video".equals(d.key)&&i==1){e.setSingleLine(false);e.setMinLines(4);e.setGravity(Gravity.TOP|Gravity.START);e.setPadding(dp(a,14),dp(a,12),dp(a,14),dp(a,12));}fs.add(e);box.addView(e,mt(a,i==0?14:8));}
  TextView next=button(a,"Devam et",Color.WHITE,ORANGE);box.addView(next,mt(a,14));next.setOnClickListener(v->{String first=fs.get(0).getText().toString().trim();if(first.isEmpty()){fs.get(0).setError("Gerekli");return;}d.title=first;try{for(int i=0;i<fs.size();i++)d.details.put("field"+i,fs.get(i).getText().toString().trim());}catch(Exception ignored){}x.dismiss();timing(a,plans,d,cb);});scroll.addView(box);x.setContentView(scroll);x.show();fit(x,a,.94f);}
 private static String[] fields(String k){if("book".equals(k))return new String[]{"Kitap adı","Güncel sayfa","Bugün kaç sayfa okuyacaksın?"};if("work".equals(k))return new String[]{"İş yeri","Çalışma düzeni (ör. 14:00–22:00)","Ek bilgi"};if("video".equals(k))return new String[]{"Video / proje adı","Aşamalar (her satıra bir aşama)","Ek bilgi"};if("sport".equals(k))return new String[]{"Spor türü","Hedef veya süre","Ek bilgi"};if("faith".equals(k))return new String[]{"İbadet / hedef","Kitap veya detay","Hedef miktar / süre"};if("appointment".equals(k))return new String[]{"Randevu","Nerede / kiminle?","Yol için kaç dakika ayırmalıyım?","Not"};if("food".equals(k))return new String[]{"Yemek / hazırlık","Miktar / kaç kişilik","Ek bilgi"};return new String[]{"Görev","Ek bilgi"};}
 private static void timing(Activity a,List<Plan> plans,Draft d,Callback cb){
  Dialog x=dialog(a);ScrollView scroll=new ScrollView(a);LinearLayout box=box(a);header(a,box,"Zamanını seç","2 / 2  ·  Son adımda plan doğrudan oluşturulur.",x);final String[] date={d.date},start={d.start},end={d.end};
  box.addView(label(a,"Tarih"),mt(a,14));TextView dateB=choice(a,pretty(date[0]));box.addView(dateB,mt(a,6));dateB.setOnClickListener(v->{Calendar c=parse(date[0]);new android.app.DatePickerDialog(a,(vv,y,m,day)->{Calendar z=Calendar.getInstance();z.set(y,m,day);date[0]=key(z);dateB.setText(pretty(date[0]));},c.get(Calendar.YEAR),c.get(Calendar.MONTH),c.get(Calendar.DAY_OF_MONTH)).show();});
  box.addView(label(a,"Plan türü"),mt(a,13));LinearLayout types=row(a);TextView timed=chip(a,"Saatli",true),all=chip(a,"Tüm gün",false);types.addView(timed,weight(a,1,48));gap(types,a,8);types.addView(all,weight(a,1,48));box.addView(types,mt(a,6));
  LinearLayout times=row(a);TextView sb=choice(a,start[0].isEmpty()?"Başlangıç":start[0]),eb=choice(a,end[0].isEmpty()?"Bitiş (isteğe bağlı)":end[0]);times.addView(sb,weight(a,1,62));gap(times,a,8);times.addView(eb,weight(a,1,62));box.addView(times,mt(a,8));
  box.addView(label(a,"Tekrar"),mt(a,13));TextView rep=choice(a,repeat(d.repeat));box.addView(rep,mt(a,6));box.addView(txt(a,"Hatırlatma süresi Ayarlar'dan yönetilir.",10,MUTED,false),mt(a,7));
  TextView create=button(a,"✓  Planı oluştur",Color.WHITE,ORANGE);box.addView(create,mt(a,14));
  sb.setOnClickListener(v->time(a,start[0],s->{start[0]=s;sb.setText(s);}));eb.setOnClickListener(v->time(a,end[0],s->{end[0]=s;eb.setText(s);}));timed.setOnClickListener(v->{d.type=Plan.HOURLY;setChip(timed,true);setChip(all,false);times.setVisibility(View.VISIBLE);});all.setOnClickListener(v->{d.type=Plan.ALL_DAY;start[0]="";end[0]="";setChip(timed,false);setChip(all,true);times.setVisibility(View.GONE);});rep.setOnClickListener(v->{Dialog r=dialog(a);LinearLayout b=box(a);header(a,b,"Tekrar","Planın ne sıklıkla tekrarlansın?",r);String[] n={"Tek sefer","Her gün","Hafta içi","Her hafta"};String[] val={Plan.REPEAT_NONE,Plan.REPEAT_DAILY,Plan.REPEAT_WEEKDAYS,Plan.REPEAT_WEEKLY};for(int i=0;i<n.length;i++){final int j=i;TextView q=button(a,n[i],TEXT,SURFACE2);b.addView(q,mt(a,7));q.setOnClickListener(vv->{d.repeat=val[j];rep.setText(repeat(d.repeat));r.dismiss();});}r.setContentView(b);r.show();fit(r,a,.84f);});
  create.setOnClickListener(v->{if(!Plan.ALL_DAY.equals(d.type)&&start[0].isEmpty()){sb.setError("Başlangıç saatini seç");return;}d.date=date[0];d.start=start[0];d.end=end[0];Plan p=new Plan(System.currentTimeMillis(),d.date,d.title,d.type,d.start,Plan.durationBetween(d.start,d.end),false);p.startTime=d.start;p.endTime=d.end;p.time=d.start;p.repeat=d.repeat;p.category=d.key;p.details=d.details.toString();p.status=Plan.STATUS_PLANNED;plans.add(p);PlanStore.save(a,plans);android.content.SharedPreferences s=a.getSharedPreferences("rotam_settings",0);ReminderScheduler.schedule(a,p,s.getInt("reminder_minutes",15),s.getBoolean("reminders",true));x.dismiss();if(cb!=null)cb.saved();});
  scroll.addView(box);x.setContentView(scroll);x.show();fit(x,a,.94f);
 }
 private interface Done{void ok(String s);} private static void time(Activity a,String old,Done cb){Dialog x=dialog(a);LinearLayout b=box(a);header(a,b,"Saat seç","Saat ve dakikayı belirle.",x);Calendar c=Calendar.getInstance();if(old!=null&&old.matches("\\d{2}:\\d{2}")){c.set(Calendar.HOUR_OF_DAY,Integer.parseInt(old.substring(0,2)));c.set(Calendar.MINUTE,Integer.parseInt(old.substring(3)));}final int[] hm={c.get(Calendar.HOUR_OF_DAY),c.get(Calendar.MINUTE)};TextView pv=txt(a,fmt(hm),38,TEXT,true);pv.setGravity(Gravity.CENTER);pv.setBackground(round(SURFACE2,20));b.addView(pv,mt(a,10));LinearLayout wheels=row(a);Wheel h=new Wheel(a,24,hm[0],v->{hm[0]=v;pv.setText(fmt(hm));});Wheel m=new Wheel(a,60,hm[1],v->{hm[1]=v;pv.setText(fmt(hm));});wheels.addView(h,weight(a,1,210));TextView colon=txt(a,":",32,TEXT,true);colon.setGravity(Gravity.CENTER);wheels.addView(colon,lp(a,28,80));wheels.addView(m,weight(a,1,210));b.addView(wheels,mt(a,8));LinearLayout acts=row(a);TextView cancel=button(a,"Vazgeç",MUTED,SURFACE2),ok=button(a,"Saati seç",Color.WHITE,ORANGE);acts.addView(cancel,weight(a,1,50));gap(acts,a,8);acts.addView(ok,weight(a,1,50));b.addView(acts,mt(a,10));cancel.setOnClickListener(v->x.dismiss());ok.setOnClickListener(v->{cb.ok(fmt(hm));x.dismiss();});x.setContentView(b);x.show();fit(x,a,.92f);}
 private static class Wheel extends View{android.graphics.Paint p=new android.graphics.Paint(1);int max,val;float off,last;Wheel(Activity a,int max,int v,Value cb){super(a);this.max=max;val=v;this.cb=cb;setBackground(round(SURFACE2,20));}Value cb;int rh(){return dp(getContext(),52);}protected void onDraw(android.graphics.Canvas c){super.onDraw(c);float mid=getHeight()/2f,r=rh();for(int i=-2;i<=2;i++){float y=mid+i*r+off,d=Math.abs(y-mid);p.setColor(d<r*.45?TEXT:MUTED);p.setTypeface(Typeface.create("sans",d<r*.45?Typeface.BOLD:Typeface.NORMAL));p.setTextSize(dp(getContext(),d<r*.45?31:24));String s=String.format(Locale.GERMANY,"%02d",wrap(val+i));c.drawText(s,getWidth()/2f-p.measureText(s)/2,y-(p.ascent()+p.descent())/2,p);}p.setColor(ORANGE);p.setStrokeWidth(dp(getContext(),2));c.drawLine(10,mid-r/2,getWidth()-10,mid-r/2,p);c.drawLine(10,mid+r/2,getWidth()-10,mid+r/2,p);}void consume(){int r=rh();while(off<=-r){off+=r;val=wrap(val+1);cb.v(val);}while(off>=r){off-=r;val=wrap(val-1);cb.v(val);}}void snap(){int r=rh();int dir=Math.abs(off)>r/2?(off<0?1:-1):0;if(dir!=0){val=wrap(val+dir);cb.v(val);}android.animation.ValueAnimator a=android.animation.ValueAnimator.ofFloat(off,0);a.setDuration(140);a.addUpdateListener(v->{off=(float)v.getAnimatedValue();invalidate();});a.start();}public boolean onTouchEvent(android.view.MotionEvent e){if(e.getActionMasked()==0){last=e.getY();return true;}if(e.getActionMasked()==2){float dy=e.getY()-last;last=e.getY();off+=dy;consume();invalidate();return true;}if(e.getActionMasked()==1){snap();return true;}return true;}int wrap(int n){int x=n%max;return x<0?x+max:x;}}
 private interface Value{void v(int x);}
 private static LinearLayout category(Activity a,String icon,String name){LinearLayout c=col(a);c.setGravity(Gravity.CENTER_VERTICAL);c.setPadding(dp(a,12),dp(a,10),dp(a,12),dp(a,10));c.setBackground(round(SURFACE,18));c.addView(txt(a,icon,23,TEXT,false));c.addView(txt(a,name,13,TEXT,true),mt(a,5));return c;}
 private static LinearLayout col(Activity a){LinearLayout l=new LinearLayout(a);l.setOrientation(LinearLayout.VERTICAL);return l;}private static LinearLayout row(Activity a){LinearLayout l=col(a);l.setOrientation(LinearLayout.HORIZONTAL);l.setGravity(Gravity.CENTER_VERTICAL);return l;}
 private static LinearLayout box(Activity a){LinearLayout l=col(a);l.setPadding(dp(a,18),dp(a,17),dp(a,18),dp(a,18));l.setBackground(round(BG,28));return l;}
 private static void header(Activity a,LinearLayout b,String t,String s,Dialog d){LinearLayout r=row(a);LinearLayout tx=col(a);tx.addView(txt(a,t,24,TEXT,true));tx.addView(txt(a,s,11,MUTED,false),mt(a,4));r.addView(tx,weight(a,1,50));TextView q=button(a,"×",TEXT,SURFACE);r.addView(q,lp(a,44,44));q.setOnClickListener(v->d.dismiss());b.addView(r);}
 private static EditText input(Activity a,String h){EditText e=new EditText(a);e.setHint(h);e.setTextColor(TEXT);e.setHintTextColor(MUTED);e.setTextSize(15);e.setPadding(dp(a,14),0,dp(a,14),0);e.setSingleLine(true);e.setBackground(round(SURFACE2,17));return e;}
 private static TextView txt(Activity a,String s,float z,int c,boolean b){TextView t=new TextView(a);t.setText(s);t.setTextSize(z);t.setTextColor(c);t.setTypeface(Typeface.create("sans",b?Typeface.BOLD:Typeface.NORMAL));t.setIncludeFontPadding(false);return t;}
 private static TextView button(Activity a,String s,int f,int bg){TextView t=txt(a,s,13,f,true);t.setGravity(Gravity.CENTER);t.setBackground(round(bg,17));return t;}
 private static TextView choice(Activity a,String s){TextView t=txt(a,s,14,TEXT,true);t.setGravity(Gravity.CENTER_VERTICAL);t.setPadding(dp(a,14),0,dp(a,14),0);t.setBackground(round(SURFACE2,17));return t;}
 private static TextView chip(Activity a,String s,boolean on){return button(a,s,on?Color.WHITE:TEXT,on?ORANGE:SURFACE2);}private static void setChip(TextView t,boolean on){t.setTextColor(on?Color.WHITE:TEXT);t.setBackground(round(on?ORANGE:SURFACE2,17));}
 private static LinearLayout.LayoutParams mt(Activity a,int n){LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.topMargin=dp(a,n);return p;}private static LinearLayout.LayoutParams weight(Activity a,float w,int h){return new LinearLayout.LayoutParams(0,dp(a,h),w);}private static LinearLayout.LayoutParams lp(Activity a,int w,int h){return new LinearLayout.LayoutParams(dp(a,w),dp(a,h));}private static void gap(LinearLayout l,Activity a,int w){l.addView(new View(a),lp(a,w,1));}
 private static GradientDrawable round(int c,int r){GradientDrawable g=new GradientDrawable();g.setColor(c);g.setCornerRadius(r);return g;}private static int dp(Activity a,int v){return (int)(v*a.getResources().getDisplayMetrics().density+.5f);}private static String label(String k){if("book".equals(k))return "Kitap / Okuma";if("work".equals(k))return "İş";if("video".equals(k))return "Video Edit";if("sport".equals(k))return "Spor";if("faith".equals(k))return "İbadet";if("appointment".equals(k))return "Randevu";if("food".equals(k))return "Yemek";return "Kişisel";}private static String repeat(String v){if(Plan.REPEAT_DAILY.equals(v))return "Her gün";if(Plan.REPEAT_WEEKDAYS.equals(v))return "Hafta içi";if(Plan.REPEAT_WEEKLY.equals(v))return "Her hafta";return "Tek sefer";}private static Calendar parse(String k){Calendar c=Calendar.getInstance();try{String[] p=k.split("-");c.set(Integer.parseInt(p[0]),Integer.parseInt(p[1])-1,Integer.parseInt(p[2]));}catch(Exception ignored){}return c;}private static String key(Calendar c){return String.format(Locale.GERMANY,"%04d-%02d-%02d",c.get(Calendar.YEAR),c.get(Calendar.MONTH)+1,c.get(Calendar.DAY_OF_MONTH));}private static String pretty(String k){return new SimpleDateFormat("EEEE · d MMMM yyyy",TR).format(parse(k).getTime());}private static String fmt(int[] h){return String.format(Locale.GERMANY,"%02d:%02d",h[0],h[1]);}
}